type IncidentEvent = { id: string; occurredAt: string; message: string };
type Props = { events: IncidentEvent[] };

export default function EventList({ events }: Props) {
  const ordered = events.sort((a, b) => a.occurredAt.localeCompare(b.occurredAt));
  return (
    <ul>
      {ordered.map(event => <li key={event.id}>{event.message}</li>)}
    </ul>
  );
}

function paginate(items, page, pageSize) {
  const start = page * pageSize;
  return items.slice(start, start + pageSize);
}

module.exports = { paginate };
